// 單調遞減雙端佇列：佇列存索引，隊頭永遠是視窗最大值
// 時間複雜度: O(n)，空間複雜度: O(k)
function maxSlidingWindow(nums, k) {
    const dq = []; // 用陣列 + head 指標模擬 deque，避免 shift() 的 O(n)
    let head = 0;
    const result = [];
    for (let i = 0; i < nums.length; i++) {
        while (dq.length > head && nums[dq[dq.length - 1]] <= nums[i])
            dq.pop(); // 比自己小的永遠不會是答案
        dq.push(i);
        if (dq[head] <= i - k)
            head++; // 隊頭滑出視窗
        if (i >= k - 1)
            result.push(nums[dq[head]]);
    }
    return result;
}

