#include <vector>
#include <deque>

class Solution {
public:
    /**
     * 方法：單調遞減佇列
     * 時間複雜度: O(n)
     * 空間複雜度: O(k)
     */
    vector<int> maxSlidingWindow(vector<int>& nums, int k) {
        if (nums.empty() || k == 0) return {};

        deque<int> dq;  // 存儲索引
        vector<int> result;

        for (int i = 0; i < nums.size(); i++) {
            // 移除超出窗口範圍的索引
            while (!dq.empty() && dq.front() < i - k + 1) {
                dq.pop_front();
            }

            // 移除所有小於當前元素的索引
            while (!dq.empty() && nums[dq.back()] < nums[i]) {
                dq.pop_back();
            }

            // 加入當前索引
            dq.push_back(i);

            // 窗口形成後，記錄最大值
            if (i >= k - 1) {
                result.push_back(nums[dq.front()]);
            }
        }

        return result;
    }
};

