// 單調遞減雙端佇列：佇列存索引，隊頭永遠是視窗最大值
// 時間複雜度: O(n)，空間複雜度: O(n)
int* maxSlidingWindow(int* nums, int numsSize, int k, int* returnSize) {
    int* dq = malloc(sizeof(int) * numsSize);
    int head = 0, tail = 0;
    int* result = malloc(sizeof(int) * (numsSize - k + 1));
    *returnSize = 0;

    for (int i = 0; i < numsSize; i++) {
        while (tail > head && nums[dq[tail - 1]] <= nums[i]) tail--;   // 比自己小的永遠不會是答案
        dq[tail++] = i;
        if (dq[head] <= i - k) head++;                                // 隊頭滑出視窗
        if (i >= k - 1) result[(*returnSize)++] = nums[dq[head]];
    }
    free(dq);
    return result;
}
